class ProductCsvMessageConverter extends AbstractHttpMessageConverter<Product> {
    ProductCsvMessageConverter() {
        super(MediaType.valueOf("text/csv"));
    }

    protected boolean supports(Class<?> clazz) { return Product.class.equals(clazz); }

    protected Product readInternal(Class<? extends Product> clazz, HttpInputMessage msg) { /* ... */ return null; }

    protected void writeInternal(Product p, HttpOutputMessage out) throws IOException {
        out.getBody().write((p.id() + "," + p.name() + "," + p.price()).getBytes());
    }
}

class CsvWebConfig implements WebMvcConfigurer {
    public void extendMessageConverters(List<HttpMessageConverter<?>> converters) {
        converters.add(new ProductCsvMessageConverter());
    }
}
